-- - api/ads/go.js, edge/jetstream/compose.ts, and all original placements/tags
--   remain byte-identical. No Cloudflare/shortener deployment is performed.
-- - No new polling/second loop is created. Job 60 remains the explicit 10s job.
begin;
set local statement_timeout='2000ms';
set local lock_timeout='1000ms';
set local idle_in_transaction_session_timeout='12000ms';

create or replace function public.nexus_v3340_norm(p_value text)
returns text
language sql
immutable
strict
parallel safe
as $function$
  select btrim(regexp_replace(
    translate(lower(p_value),
      'áàâãäåéèêëíìîïóòôõöúùûüçñýÿæœÁÀÂÃÄÅÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑÝŸÆŒ’',
      'aaaaaaeeeeiiiiooooouuuucnyyaoAAAAAAEEEEIIIIOOOOOUUUUCNYYAO '),
    '[^a-z0-9]+',' ','g'));
$function$;

create table if not exists public.nexus_v3340_travel_lexicon (
  lexicon_id             bigint generated always as identity primary key,
  country_code           text not null,
  primary_locale         text not null,
  locale_codes           text[] not null,
  admin_area             text not null,
  destination_name       text not null,
  destination_key        text generated always as (public.nexus_v3340_norm(destination_name)) stored,
  aliases                text[] not null,
  intent_terms           text[] not null,
  eligible_networks      text[] not null,
  verified_networks      text[] not null,
  source_documents       text[] not null,
  source_sha256          text[] not null,
  source_claim_scope     text not null,
  embedding_source       text not null,
  embedding              public.halfvec(384) not null,
  embedding_model        text not null,
  cosine_threshold       numeric(5,4) not null,
  disclosure_tag         text not null,
  installed_by_release   text not null,
  created_at             timestamptz not null default clock_timestamp(),
  updated_at             timestamptz not null default clock_timestamp(),
  constraint nexus_v3340_country_ck check(country_code in('US','CA','ES','FR','IT','GB')),
  constraint nexus_v3340_primary_locale_ck check(primary_locale=any(locale_codes)),
  constraint nexus_v3340_network_subset_ck check(verified_networks<@eligible_networks),
  constraint nexus_v3340_source_scope_ck check(source_claim_scope='operator_reference_not_independently_verified'),
  constraint nexus_v3340_model_ck check(embedding_model='gte-small'),
  constraint nexus_v3340_threshold_ck check(cosine_threshold between 0.75 and 0.95),
  constraint nexus_v3340_disclosure_ck check(disclosure_tag='#ad'),
  constraint nexus_v3340_release_ck check(installed_by_release='v3340.0'),
  constraint nexus_v3340_country_destination_uq unique(country_code,destination_key)
);

revoke all on table public.nexus_v3340_travel_lexicon
  from public,anon,authenticated,service_role;
revoke all on sequence public.nexus_v3340_travel_lexicon_lexicon_id_seq
  from public,anon,authenticated,service_role;

