      ('GB','en-GB',array['en-GB']::text[],'England','Oxford',array['Oxford']::text[],array['booking_uk','ebay_epn']::text[],array['booking_uk','ebay_epn']::text[],array['lista_mundial_cidades_busca.pdf','cidades_mais_buscadas_booking 2.pdf']::text[],array['b25be5cc7171443de1d3177f4cb6bcd5aa223313ea9032b60ca9aa94ede22d89','72dab6316bf2023da82405724fa8ed75da066172dd24b8049dcceeb7dad9ab38']::text[],'Travel destination: Oxford, England, United Kingdom. Hotel accommodation flight trip tourism booking.'),
      ('GB','en-GB',array['en-GB']::text[],'England','Cambridge',array['Cambridge']::text[],array['booking_uk','ebay_epn']::text[],array['booking_uk','ebay_epn']::text[],array['lista_mundial_cidades_busca.pdf','cidades_mais_buscadas_booking 2.pdf']::text[],array['b25be5cc7171443de1d3177f4cb6bcd5aa223313ea9032b60ca9aa94ede22d89','72dab6316bf2023da82405724fa8ed75da066172dd24b8049dcceeb7dad9ab38']::text[],'Travel destination: Cambridge, England, United Kingdom. Hotel accommodation flight trip tourism booking.'),
      ('GB','en-GB',array['en-GB']::text[],'England','York',array['York']::text[],array['booking_uk','ebay_epn']::text[],array['booking_uk','ebay_epn']::text[],array['lista_mundial_cidades_busca.pdf','cidades_mais_buscadas_booking 2.pdf']::text[],array['b25be5cc7171443de1d3177f4cb6bcd5aa223313ea9032b60ca9aa94ede22d89','72dab6316bf2023da82405724fa8ed75da066172dd24b8049dcceeb7dad9ab38']::text[],'Travel destination: York, England, United Kingdom. Hotel accommodation flight trip tourism booking.')
    ) as s(country_code,primary_locale,locale_codes,admin_area,destination_name,
           aliases,eligible_networks,verified_networks,source_documents,
           source_sha256,embedding_source)
    join jsonb_to_recordset(v_payload->'rows')
      as e(country_code text,destination_name text,embedding jsonb)
      using(country_code,destination_name)
    on conflict(country_code,destination_key) do update set
      primary_locale=excluded.primary_locale,
      locale_codes=excluded.locale_codes,
      admin_area=excluded.admin_area,
      destination_name=excluded.destination_name,
      aliases=excluded.aliases,
      intent_terms=excluded.intent_terms,
      eligible_networks=excluded.eligible_networks,
      verified_networks=excluded.verified_networks,
      source_documents=excluded.source_documents,
      source_sha256=excluded.source_sha256,
      source_claim_scope=excluded.source_claim_scope,
      embedding_source=excluded.embedding_source,
      embedding=excluded.embedding,
      embedding_model=excluded.embedding_model,
      cosine_threshold=excluded.cosine_threshold,
      disclosure_tag=excluded.disclosure_tag,
      installed_by_release=excluded.installed_by_release,
      updated_at=excluded.updated_at;

    get diagnostics v_rows=row_count;
    if v_rows<>92 or (select count(*) from public.nexus_v3340_travel_lexicon)<>92 then
      raise exception 'v3340 travel lexicon did not resolve to exactly 92 rows';
    end if;
    perform set_config('nexus.v3340_travel_embeddings_json','',true);
    v_payload:=null;
  exception when others then
    perform set_config('nexus.v3340_travel_embeddings_json','',true);
    v_payload:=null;
    raise;
  end;
end
$install$;

create index if not exists nexus_v3340_travel_country_locale_idx
  on public.nexus_v3340_travel_lexicon(country_code,primary_locale,destination_key);
create index if not exists nexus_v3340_travel_embedding_hnsw_idx
  on public.nexus_v3340_travel_lexicon
  using hnsw(embedding public.halfvec_cosine_ops)
  with(m=12,ef_construction=48);

-- Service-role-only, data-only travel resolver.
create or replace function public.nexus_v3340_resolve_travel(
  p_headers jsonb,
  p_destination text,
  p_intent_text text,
  p_intent_embedding text,
  p_locale text default null,
  p_preferred_network text default null
) returns jsonb
language plpgsql
security definer
set search_path='public','extensions','pg_temp'
as $function$
declare
  v_country text;
  v_source text;
  v_dest_key text;
  v_intent_key text;
  v_locale text;
  v_network text;
  v_query public.halfvec(384);
  v_similarity numeric;
  v_route_ready boolean:=false;
  v_catalog_rows integer:=0;
  v_campaign text;
  v_booking_aid text;
  v_kms text;
  v_host text;
  v_copy text;
  r public.nexus_v3340_travel_lexicon%rowtype;
begin
  perform set_config('statement_timeout','2000',true);
  perform set_config('lock_timeout','1000',true);
  begin
    if p_headers is null or jsonb_typeof(p_headers)<>'object' then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','headers_invalidos','affiliate_url',null);
    end if;
    select upper(btrim(e.value)),lower(e.key) into v_country,v_source
      from jsonb_each_text(p_headers)e
     where lower(e.key) in('cf-ipcountry','x-vercel-ip-country')
       and btrim(e.value)<>''
     order by case lower(e.key) when 'cf-ipcountry' then 0 else 1 end,
              lower(e.key),e.key,e.value
     limit 1;
    if v_country is null or v_country!~'^[A-Z]{2}$' or v_country in('XX','T1') then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','cdn_country_unavailable','affiliate_url',null,'human_or_residential_proven',false);
    end if;
    if v_country not in('US','CA','ES','FR','IT','GB') then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','country_outside_v3340_scope','country',v_country,'affiliate_url',null,'human_or_residential_proven',false);
    end if;
    if p_destination is null or length(btrim(p_destination)) not between 2 and 100
       or p_intent_text is null or length(btrim(p_intent_text)) not between 3 and 500
       or p_intent_embedding is null or length(p_intent_embedding)>12000 then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','payload_invalid','country',v_country,'affiliate_url',null);
    end if;

    v_dest_key:=public.nexus_v3340_norm(p_destination);
    v_intent_key:=public.nexus_v3340_norm(p_intent_text);
    select l.* into r from public.nexus_v3340_travel_lexicon l
     where l.country_code=v_country
       and exists(select 1 from unnest(l.aliases)a
                   where public.nexus_v3340_norm(a)=v_dest_key)
     limit 1;
    if not found then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','destination_not_in_country_lexicon','country',v_country,'affiliate_url',null);
    end if;

    v_locale:=coalesce(nullif(btrim(p_locale),''),r.primary_locale);
    if not exists(select 1 from unnest(r.locale_codes)x where lower(x)=lower(v_locale)) then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','locale_not_supported_for_destination','country',v_country,'destination',r.destination_name,'supported_locales',r.locale_codes,'affiliate_url',null);
    end if;
    if not exists(select 1 from unnest(r.aliases)a
      where v_intent_key~('(^| )'||public.nexus_v3340_norm(a)||'( |$)')) then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','destination_absent_from_intent','country',v_country,'destination',r.destination_name,'affiliate_url',null);
    end if;
    if not exists(select 1 from unnest(r.intent_terms)t
      where v_intent_key~('(^| )'||public.nexus_v3340_norm(t)||'( |$)')) then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','travel_intent_not_explicit','country',v_country,'destination',r.destination_name,'affiliate_url',null);
    end if;

    begin
      v_query:=p_intent_embedding::public.halfvec(384);
    exception when others then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','embedding_invalid','country',v_country,'destination',r.destination_name,'affiliate_url',null);
    end;
    v_similarity:=1-(r.embedding<=>v_query);
    if v_similarity is null or v_similarity<r.cosine_threshold then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','cosine_threshold_not_met','country',v_country,'destination',r.destination_name,'cosine_similarity',round(v_similarity,6),'cosine_threshold',r.cosine_threshold,'operator','<=>','affiliate_url',null);
    end if;

    v_network:=lower(coalesce(nullif(btrim(p_preferred_network),''),
      case when v_country='GB' then 'booking_uk'
           when v_country in('US','CA') then 'ebay_epn' else '' end));
    if v_network<>'' and not v_network=any(r.eligible_networks) then
      return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','network_not_eligible_for_branch','country',v_country,'destination',r.destination_name,'eligible_networks',r.eligible_networks,'affiliate_url',null);
    end if;

    if v_network='ebay_epn' and v_country in('US','CA','GB') then
      v_host:=case v_country when 'US' then 'www.ebay.com' when 'CA' then 'www.ebay.ca' else 'www.ebay.co.uk' end;
      begin
        select value into strict v_kms from public.nexus_growth_secrets where key='nexus_satellites_kms';
        select extensions.pgp_sym_decrypt(decode(value,'hex'),v_kms)::jsonb->>'campaign_id'
          into strict v_campaign from public.nexus_growth_secrets where key='ebay_campaign_id_enc';
        select count(*) into v_catalog_rows from public.ads
         where active and advertiser ilike '%ebay%'
           and lower(substring(click_url from '^https?://([^/]+)'))=v_host
           and position(v_campaign in click_url)>0;
        v_route_ready:=v_catalog_rows>0;
        v_campaign:=null;v_kms:=null;
      exception when others then
        v_route_ready:=false;v_campaign:=null;v_kms:=null;
      end;
    elsif v_network='booking_uk' and v_country='GB' then
      begin
        select value into strict v_kms from public.nexus_growth_secrets where key='nexus_satellites_kms';
        select extensions.pgp_sym_decrypt(decode(value,'hex'),v_kms)::jsonb->>'aid'
          into strict v_booking_aid from public.nexus_growth_secrets where key='booking_uk_id_enc';
        select count(*) into v_catalog_rows from public.ads
         where active and advertiser='Booking.com United Kingdom'
           and cj_link_id=v_booking_aid;
        v_route_ready:=v_catalog_rows>0;
        v_booking_aid:=null;v_kms:=null;
      exception when others then
        v_route_ready:=false;v_booking_aid:=null;v_kms:=null;
      end;
    end if;

    v_copy:=case lower(v_locale)
      when 'es-es' then 'Opciones de viaje para '||r.destination_name||'. Consulta disponibilidad y condiciones actuales en la página del socio.'
      when 'fr-fr' then 'Options de voyage pour '||r.destination_name||'. Vérifiez les disponibilités et les conditions actuelles sur la page du partenaire.'
      when 'fr-ca' then 'Options de voyage pour '||r.destination_name||'. Vérifiez les disponibilités et les conditions actuelles sur la page du partenaire.'
      when 'it-it' then 'Opzioni di viaggio per '||r.destination_name||'. Verifica disponibilità e condizioni attuali sulla pagina del partner.'
      else 'Travel options for '||r.destination_name||'. Check current availability and terms on the partner page.' end;

    return jsonb_build_object(
      'version','v3340.0','estado',case when v_route_ready then 'ok' else 'Sintonizado em Análise' end,
      'motivo',case when v_route_ready then 'verified_catalog_route_available' else 'affiliate_route_unverified' end,
      'country',v_country,'geo_source',v_source,'destination',r.destination_name,
      'admin_area',r.admin_area,'locale',v_locale,'supported_locales',r.locale_codes,
      'lexicon_match',true,'travel_intent_explicit',true,
      'cosine_operator','<=>','cosine_similarity',round(v_similarity,6),
      'cosine_threshold',r.cosine_threshold,'embedding_model',r.embedding_model,
      'eligible_networks',r.eligible_networks,'selected_network',nullif(v_network,''),
      'verified_networks',r.verified_networks,'catalog_route_ready',v_route_ready,
      'catalog_route_rows',v_catalog_rows,
      'content_copy',v_copy,'disclosure_required_before_link',r.disclosure_tag,
      'disclosure_own_line',true,'affiliate_url',null,'shortener_path',null,
      'redirect_performed',false,'click_recorded',false,
      'tracking_identifiers_appended',false,'price_adapted',false,
      'cdn_country_is_routing_hint',true,'timezone_proven',false,
      'human_or_residential_proven',false,'high_frequency_throughput_proven',false,
      'sub_1ms_guaranteed',false,'fallback_anti_404_deployed',false,
      'sub_50ms_fallback_guaranteed',false,'commission_lossless_guaranteed',false);
  exception when others then
    begin
      perform public.nexus_v420_sintonizado('v3340-travel-route',coalesce(v_country,'unknown'),sqlstate||': '||left(sqlerrm,220));
    exception when others then null;
    end;
    return jsonb_build_object('version','v3340.0','estado','Sintonizado em Análise','motivo','resolver_error','affiliate_url',null);
  end;
end
$function$;

revoke all on function public.nexus_v3340_resolve_travel(jsonb,text,text,text,text,text)
  from public,anon,authenticated,service_role;
grant execute on function public.nexus_v3340_resolve_travel(jsonb,text,text,text,text,text)
  to service_role;

create or replace function public.nexus_v3340_operator_status()
returns jsonb
language plpgsql
security definer
set search_path='public','cron','extensions','pg_temp'
as $function$
declare
  v_logged boolean:=false;
  v_kms text;
  v_book text;
  v_ebay text;
  v_book_ready boolean:=false;
  v_ebay_us integer:=0;
  v_ebay_ca integer:=0;
  v_ebay_gb integer:=0;
  v_epc7 numeric;
  v_epc3 numeric;
begin
  perform set_config('statement_timeout','2000',true);
  perform set_config('lock_timeout','1000',true);
  begin
    select relpersistence='p' into v_logged from pg_class
     where oid='public.nexus_v3340_travel_lexicon'::regclass;
    begin
      select value into strict v_kms from public.nexus_growth_secrets where key='nexus_satellites_kms';
      select extensions.pgp_sym_decrypt(decode(value,'hex'),v_kms)::jsonb->>'aid'
        into strict v_book from public.nexus_growth_secrets where key='booking_uk_id_enc';
      select extensions.pgp_sym_decrypt(decode(value,'hex'),v_kms)::jsonb->>'campaign_id'
        into strict v_ebay from public.nexus_growth_secrets where key='ebay_campaign_id_enc';
      select exists(select 1 from public.ads where active
        and advertiser='Booking.com United Kingdom' and cj_link_id=v_book),
        max(epc_7d_value),max(epc_3m_value)
        into v_book_ready,v_epc7,v_epc3 from public.ads
       where active and advertiser='Booking.com United Kingdom' and cj_link_id=v_book;
      select count(*) filter(where lower(substring(click_url from '^https?://([^/]+)'))='www.ebay.com'),
             count(*) filter(where lower(substring(click_url from '^https?://([^/]+)'))='www.ebay.ca'),
             count(*) filter(where lower(substring(click_url from '^https?://([^/]+)'))='www.ebay.co.uk')
        into v_ebay_us,v_ebay_ca,v_ebay_gb
        from public.ads where active and advertiser ilike '%ebay%' and position(v_ebay in click_url)>0;
      v_book:=null;v_ebay:=null;v_kms:=null;
    exception when others then
      v_book_ready:=false;v_ebay_us:=0;v_ebay_ca:=0;v_ebay_gb:=0;
      v_book:=null;v_ebay:=null;v_kms:=null;
    end;
    return jsonb_build_object(
      'version','v3340.0','observed_at',clock_timestamp(),
      'lexicon',jsonb_build_object(
        'relation_logged',v_logged,'rows',(select count(*) from public.nexus_v3340_travel_lexicon),
        'countries',(select jsonb_object_agg(country_code,n order by country_code) from (select country_code,count(*)n from public.nexus_v3340_travel_lexicon group by country_code)x),
        'embedding_model','gte-small','embedding_dimensions',384,
        'all_vectors_valid',(select bool_and(vector_dims(embedding)=384) from public.nexus_v3340_travel_lexicon),
        'cosine_operator','<=>','cosine_threshold',0.8000,
        'source_scope','operator_reference_not_independently_verified'),
      'affiliate_readiness',jsonb_build_object(
        'US',jsonb_build_object('ebay_epn',v_ebay_us>0,'booking_global',false),
        'CA',jsonb_build_object('ebay_epn',v_ebay_ca>0,'booking_global',false),
        'ES',jsonb_build_object('booking_global',false),
        'FR',jsonb_build_object('booking_global',false),
        'IT',jsonb_build_object('booking_global',false),
        'GB',jsonb_build_object('ebay_epn',v_ebay_gb>0,'booking_uk',v_book_ready)),
      'catalog_evidence',jsonb_build_object(
        'ebay_us_active_rows',v_ebay_us,'ebay_ca_active_rows',v_ebay_ca,'ebay_gb_active_rows',v_ebay_gb,
        'booking_uk_active',v_book_ready,'booking_uk_epc_7d_current',v_epc7,
        'booking_uk_epc_3m_current',v_epc3,
        'operator_epc_328_20_matches_current_catalog',coalesce(v_epc7=328.20,false)),
      'catalogs',jsonb_build_object(
        'ads_read_only_count',(select count(*) from public.ads),
        'active_ads_read_only_count',(select count(*) from public.ads where active),
        'canonical_keyword_count',(select count(*) from public.nexus_v370_keyword_source),
        'preexisting_local_vector_count',(select count(*) from public.nexus_v380_keyword_vectors)),
      'runtime',jsonb_build_object(
        'database_resolver_ready',true,
        'supabase_edge_deployed',exists(
          select 1 from public.nexus_v3000_capability_registry
           where capability='v3340_edge_deployment' and enabled
             and evidence->>'supabase_edge_deployed'='true'
        ),
        'cloudflare_pages_deployed',false,'shortener_modified',false,
        'go_modified',false,'compose_modified',false,'polling_job_created',false),
      'telegram',jsonb_build_object(
        'job_60',(select jsonb_build_object('active',active,'schedule',schedule,'command',command) from cron.job where jobid=60),
        'master_outbox_persistence',(select case relpersistence when 'u' then 'UNLOGGED' else 'NOT_UNLOGGED' end from pg_class where oid='public.nexus_v420_channel_outbox'::regclass),
        'satellite_outbox_persistence',(select case relpersistence when 'p' then 'LOGGED' else 'NOT_LOGGED' end from pg_class where oid='public.nexus_v1550_outbox_logged'::regclass),
        'pacing_per_destination','3/min and 40/hour',
        'channels',(select jsonb_agg(jsonb_build_object('channel_key',channel_key,'chat_id',chat_id,'source_relation',source_relation,'enabled',enabled) order by channel_key) from public.nexus_v420_channel_routes where channel_key in('grupo_cliques','atendimento'))),
      'cumulative',jsonb_build_object(
        'shein_v3330_preserved',coalesce((public.nexus_v3330_operator_status()#>>'{vault,installed}')::boolean,false),
        'amazon_v3320_preserved',coalesce((public.nexus_v3320_operator_status()#>>'{regional_readiness,BR}')::boolean,false),
        'aliexpress_v3310_preserved',coalesce((public.nexus_v3310_operator_status()#>>'{vault,installed}')::boolean,false)),
      'policy',jsonb_build_object('copy_policy_version','v3200.0','activation_profile','v3340.0','disclosure_own_line_before_link',true),
      'claims',jsonb_build_object(
        'cdn_country_proves_timezone',false,'human_or_residential_proven',false,
        'high_frequency_throughput_proven',false,'sub_1ms_guaranteed',false,
        'fallback_anti_404_deployed',false,'sub_50ms_fallback_guaranteed',false,
        'commission_lossless_guaranteed',false,'redirect_performed',false,'click_recorded',false));
  exception when others then
    begin perform public.nexus_v420_sintonizado('v3340-operator-status',null,sqlstate||': '||left(sqlerrm,220)); exception when others then null; end;
    return jsonb_build_object('version','v3340.0','state','Sintonizado em Análise','observed_at',clock_timestamp());
  end;
end
$function$;

revoke all on function public.nexus_v3340_operator_status()
  from public,anon,authenticated,service_role;
grant execute on function public.nexus_v3340_operator_status() to service_role;

update public.nexus_v3200_copy_policies
   set active=true,
       directives=directives||jsonb_build_object(
         'activation_profile','v3340.0','travel_locales',jsonb_build_array('en-US','en-CA','fr-CA','es-ES','fr-FR','it-IT','en-GB'),
         'travel_disclosure_tier1','#ad','disclosure_own_line_before_link',true,
         'travel_neutral_factual_copy',true,'travel_countdown_allowed',false,
         'travel_fake_endorsement_allowed',false,'cdn_country_is_human_proof',false,
         'cloudflare_pages_deployed',false,'shortener_modified',false,
         'fallback_anti_404_deployed',false,'sub_1ms_guaranteed',false,
         'sub_50ms_fallback_guaranteed',false,'commission_lossless_guaranteed',false),
       checked_at=clock_timestamp()
 where policy_version='v3200.0';

insert into public.nexus_v3000_capability_registry(capability,enabled,evidence,checked_at) values
 ('v3340_travel_lexicon',true,jsonb_build_object('rows',92,'countries',jsonb_build_object('US',26,'CA',15,'ES',14,'FR',12,'IT',13,'GB',12),'relation_logged',true,'source_scope','operator_reference_not_independently_verified'),clock_timestamp()),
 ('v3340_travel_vectors',true,jsonb_build_object('rows',92,'model','gte-small','dimensions',384,'operator','<=>','metric','cosine_distance','threshold',0.8000,'preexisting_canonical_vectors_mutated',false),clock_timestamp()),
 ('v3340_affiliate_routes',true,jsonb_build_object('US',jsonb_build_object('ebay_epn',true,'booking_global',false),'CA',jsonb_build_object('ebay_epn',true,'booking_global',false),'ES',jsonb_build_object('booking_global',false),'FR',jsonb_build_object('booking_global',false),'IT',jsonb_build_object('booking_global',false),'GB',jsonb_build_object('booking_uk',true,'ebay_epn',true),'redirect_enabled',false),clock_timestamp()),
 ('v3340_booking_epc_claim',false,jsonb_build_object('operator_claim_usd',328.20,'current_catalog_epc_7d',9.35,'current_catalog_epc_3m',11.15,'reason','operator claim does not match current active Booking UK catalog row'),clock_timestamp()),
 ('v3340_edge_deployment',false,jsonb_build_object('supabase_edge_deployed',false,'cloudflare_pages_deployed',false,'shortener_modified',false,'go_modified',false,'compose_modified',false,'reason','pending physical Supabase postdeploy evidence; Cloudflare credential invalid'),clock_timestamp()),
 ('v3340_fallback_anti_404',false,jsonb_build_object('cloudflare_credential_currently_valid',false,'verified_kv_binding',false,'anti_404_path',false,'sub_50ms_guaranteed',false,'commission_lossless_guaranteed',false),clock_timestamp())
on conflict(capability) do update set enabled=excluded.enabled,evidence=excluded.evidence,checked_at=excluded.checked_at;

-- Atomic catalog, vector, ACL, cumulative and Telegram assertions.
do $assert$
declare
  v_persistence "char";
  v_status jsonb;
begin
  if (select count(*) from public.nexus_v3340_travel_lexicon)<>92 then raise exception 'v3340 row count failed'; end if;
  if (select jsonb_object_agg(country_code,n order by country_code) from (select country_code,count(*)n from public.nexus_v3340_travel_lexicon group by country_code)x)
     <>jsonb_build_object('US',26,'CA',15,'ES',14,'FR',12,'IT',13,'GB',12) then raise exception 'v3340 country matrix failed'; end if;
  if exists(select 1 from public.nexus_v3340_travel_lexicon where vector_dims(embedding)<>384 or embedding_model<>'gte-small') then raise exception 'v3340 vector dimensions/model failed'; end if;
  if (select count(distinct encode(extensions.digest(embedding::text,'sha256'),'hex')) from public.nexus_v3340_travel_lexicon)<>92 then raise exception 'v3340 embeddings are not unique'; end if;
  select relpersistence into v_persistence from pg_class where oid='public.nexus_v3340_travel_lexicon'::regclass;
  if v_persistence<>'p'::"char" then raise exception 'v3340 lexicon is not LOGGED'; end if;
  if (select count(*) from public.ads)<>14301 or (select count(*) from public.ads where active)<>12165 or (select count(*) from public.nexus_v370_keyword_source)<>17605 or (select count(*) from public.nexus_v380_keyword_vectors)<>11568 then raise exception 'v3340 read-only catalogs drifted'; end if;
  if not exists(select 1 from public.nexus_shein_campaign_vault where network_id=7)
     or not exists(select 1 from public.nexus_amazon_campaign_vault where network_id=6 and region_code='BR')
     or not exists(select 1 from public.nexus_aliexpress_campaign_vault where network_id=5) then raise exception 'v3340 cumulative vault invariant failed'; end if;
  if has_table_privilege('anon','public.nexus_v3340_travel_lexicon','select') or has_table_privilege('authenticated','public.nexus_v3340_travel_lexicon','select') or has_table_privilege('service_role','public.nexus_v3340_travel_lexicon','select') then raise exception 'v3340 lexicon table exposed'; end if;
  if has_function_privilege('anon','public.nexus_v3340_resolve_travel(jsonb,text,text,text,text,text)','execute') or has_function_privilege('authenticated','public.nexus_v3340_resolve_travel(jsonb,text,text,text,text,text)','execute') or not has_function_privilege('service_role','public.nexus_v3340_resolve_travel(jsonb,text,text,text,text,text)','execute') then raise exception 'v3340 resolver ACL failed'; end if;
  if has_function_privilege('anon','public.nexus_v3340_operator_status()','execute') or has_function_privilege('authenticated','public.nexus_v3340_operator_status()','execute') or not has_function_privilege('service_role','public.nexus_v3340_operator_status()','execute') then raise exception 'v3340 status ACL failed'; end if;
  if not exists(select 1 from cron.job where jobid=60 and active and jobname='v360-tg-flush-10s' and schedule='10 seconds' and command='select public.nexus_v1510_flush_event(40);') then raise exception 'Job 60 drifted'; end if;
  if exists(select 1 from cron.job where jobid in(15,16,64) and active) then raise exception 'protected high-frequency jobs reactivated'; end if;
  select relpersistence into v_persistence from pg_class where oid='public.nexus_v420_channel_outbox'::regclass;
  if v_persistence<>'u'::"char" then raise exception 'master outbox not UNLOGGED'; end if;
  select relpersistence into v_persistence from pg_class where oid='public.nexus_v1550_outbox_logged'::regclass;
  if v_persistence<>'p'::"char" then raise exception 'satellite outbox not LOGGED'; end if;
  if not exists(select 1 from public.nexus_v420_channel_routes where channel_key='grupo_cliques' and enabled and chat_id=-1004417007577 and source_relation='public.ads_clicks') or not exists(select 1 from public.nexus_v420_channel_routes where channel_key='atendimento' and enabled and chat_id=-1003951454560 and source_relation='public.nexus_v385_nostr_mentions') then raise exception 'CLIQUES/ATENDIMENTO separation drifted'; end if;
  v_status:=public.nexus_v3340_operator_status();
  if v_status#>>'{catalog_evidence,operator_epc_328_20_matches_current_catalog}'<>'false' or (v_status#>>'{catalog_evidence,booking_uk_epc_7d_current}')::numeric<>9.35 or (v_status#>>'{catalog_evidence,booking_uk_epc_3m_current}')::numeric<>11.15 then raise exception 'Booking UK EPC truth boundary failed'; end if;
end
$assert$;

commit;
